import type {Suggestion} from '../../assets/modules/github/filter-input'
import {BaseFilterElement} from '../../assets/modules/github/filter-input'
import {controller} from '@github/catalyst'
import {AT_COPILOT_VALUE} from '@github-ui/filter/providers'
import {isFeatureEnabled} from '@github-ui/feature-flags'

// eslint-disable-next-line i18n-text/no-en
const COPILOT_DESCRIPTION = 'Your AI pair programmer'
const COPILOT_DISPLAY_LOGIN = 'Copilot'

@controller
class CodeScanningAlertFilterElement extends BaseFilterElement {
  override selectorOfElementToActivateOnBlur = '.js-alert-list'
  protected isCopilotEnabled: boolean | undefined

  override async fetchSuggestionsForQualifier(qualifier: string): Promise<Suggestion[]> {
    switch (this.removeNegationFromQualifierIfSupported(qualifier)) {
      case 'branch':
        return this.fetchSuggestionsForBranchQualifier()
      default:
        return super.fetchSuggestionsForQualifier(qualifier)
    }
  }

  override async fetchMatchingSuggestions(qualifier: string, filterString: string): Promise<Suggestion[]> {
    switch (this.removeNegationFromQualifierIfSupported(qualifier)) {
      case 'assignee':
        return this.fetchMatchingAssigneeSuggestions(qualifier, filterString)
      default:
        return super.fetchMatchingSuggestions(qualifier, filterString)
    }
  }

  // Retrieves the suggested refs, extracts any related to branches
  // (not tags) and returns new suggestions that are those branches'
  // names (excluding the 'refs/heads/' prefix)
  async fetchSuggestionsForBranchQualifier(): Promise<Suggestion[]> {
    const refSuggestions = await this.fetchSuggestionsForQualifier('ref')
    const branchNameSuggestions = []
    const branchRefPrefix = 'refs/heads/'
    for (const suggestion of refSuggestions) {
      if (suggestion.value.startsWith(branchRefPrefix)) {
        branchNameSuggestions.push({value: suggestion.value.substring(branchRefPrefix.length)})
      }
    }

    return branchNameSuggestions
  }

  async fetchMatchingAssigneeSuggestions(qualifier: string, filterString: string): Promise<Suggestion[]> {
    const suggestionPathAttribute = `data-suggestable-${qualifier}-path`
    const baseUrl = this.searchInput.getAttribute(suggestionPathAttribute)
    if (!baseUrl) {
      return [] // No base URL means no suggestions available
    }
    const lastSearchTerm = filterString.split(',').pop() || ''

    const url = new URL(baseUrl, window.location.origin)
    url.searchParams.append('q', lastSearchTerm)

    const userSuggestions = await this.cachedJSON(url.toString())
    const assigneeSuggestions = (
      userSuggestions as {users: Array<{login: string; name: string; isCopilot?: boolean}>}
    ).users.map((user: {login: string; name: string; isCopilot?: boolean}) => {
      if (user.isCopilot) {
        this.isCopilotEnabled = true
      }
      return {
        value: `${qualifier}:${user.login}`,
        description: user.isCopilot ? COPILOT_DESCRIPTION : user.name,
      }
    })

    // If `lastSearchTerm` exists and is included in "@copilot" (case insensitive),
    // we add Copilot to `assigneeSuggestions`. We need this condition because
    // `userSuggestions` above only contains Copilot when there is no search term.
    if (
      isFeatureEnabled('copilot_security_alert_assignee_options') &&
      lastSearchTerm &&
      AT_COPILOT_VALUE.toLowerCase().includes(lastSearchTerm.trim().toLowerCase())
    ) {
      // Check if Copilot is included as the first suggestion when there is no search term.
      // If Copilot is included is this case, then we know that Copilot is enabled for the repo/org.
      if (this.isCopilotEnabled === undefined) {
        const userSuggestionsNoSearchTerm = await this.cachedJSON(new URL(baseUrl, window.location.origin).toString())
        this.isCopilotEnabled = (userSuggestionsNoSearchTerm as {users: Array<{isCopilot?: boolean}>}).users[0]
          ?.isCopilot
          ? true
          : false
      }

      if (this.isCopilotEnabled) {
        // We keep the Copilot suggestion pinned at the top of the suggestion list
        // when relevant search terms are entered. This differs from the behavior
        // in the issues filter search bar, but matches the behavior in the issues
        // assignee filter dropdown and in the assignee picker.
        assigneeSuggestions.unshift({
          value: `${qualifier}:${COPILOT_DISPLAY_LOGIN}`,
          description: COPILOT_DESCRIPTION,
        })
      }
    }

    return assigneeSuggestions
  }

  override handleSelectedSuggestionResultEvent(event: Event) {
    const selectedSuggestion = event.target as Element

    // Check if the selected suggestion is Copilot and update to '@copilot' if so
    const dataValue = selectedSuggestion.getAttribute('data-value')
    if (dataValue === `assignee:${COPILOT_DISPLAY_LOGIN}`) {
      selectedSuggestion.setAttribute('data-value', `assignee:${AT_COPILOT_VALUE}`)
    }

    super.handleSelectedSuggestionResultEvent(event)
  }

  override invalidSearchTerms(): string | null {
    const validQualifiers = this.fetchQualifierSuggestions().map(q => q.value)
    const parts = this.searchInput.value.match(/[^\s:]+:(?:"(?:\\"|.)*?"|[^\s]*)|[^\s]+/g) || []

    const invalidParts = parts.filter(part => {
      const colonIndex = part.indexOf(':')

      if (colonIndex === -1) {
        // It's free text so never invalid
        return false
      } else {
        // If we have typed a ':', it must fully match a valid qualifier
        const typedQualifier = this.removeNegationFromQualifierIfSupported(part.substr(0, colonIndex + 1))
        return !validQualifiers.some(validQualifier => validQualifier === typedQualifier)
      }
    })

    if (invalidParts.length === 0) {
      return null
    }

    return invalidParts.join(' ')
  }
}
